import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../../components/Sidebar";
import "../../styles/Lesson.css";

// Psychology lessons with videos
const PSYCHOLOGY_LESSONS = [
  { lesson_number: 1, title: "Introduction to Psychology", videos: [{ id: 1, title: "What is Psychology?", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Research Methods", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Ethics in Psychology", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Perspectives in Psychology", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Psychology Careers", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 2, title: "Biological Bases of Behavior", videos: [{ id: 1, title: "The Brain & Nervous System", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Neurotransmitters", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Brain Imaging", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Genes & Environment", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Sleep & Dreams", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 3, title: "Sensation & Perception", videos: [{ id: 1, title: "Sensation Basics", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Vision", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Hearing", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Other Senses", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Perceptual Organization", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 4, title: "Learning", videos: [{ id: 1, title: "Classical Conditioning", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Operant Conditioning", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Observational Learning", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Reinforcement & Punishment", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Learning Applications", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 5, title: "Memory", videos: [{ id: 1, title: "Memory Processes", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Types of Memory", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Forgetting", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Memory Improvement", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "False Memories", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 6, title: "Cognition & Language", videos: [{ id: 1, title: "Thinking & Problem Solving", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Decision Making", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Language Basics", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Language Development", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Cognition & Culture", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 7, title: "Development", videos: [{ id: 1, title: "Nature vs Nurture", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Prenatal & Infancy", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Childhood Development", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Adolescence", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Adulthood & Aging", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 8, title: "Personality & Individual Differences", videos: [{ id: 1, title: "Personality Theories", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Trait Approaches", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Intelligence", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Measuring Personality", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Self Concept", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 9, title: "Abnormal Psychology", videos: [{ id: 1, title: "Defining Abnormality", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Anxiety Disorders", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Mood Disorders", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Schizophrenia", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Personality Disorders", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] },
  { lesson_number: 10, title: "Social & Applied Psychology", videos: [{ id: 1, title: "Social Influences", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 2, title: "Attitudes & Persuasion", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 3, title: "Group Behavior", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 4, title: "Therapy & Treatment", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }, { id: 5, title: "Psychology in the Real World", url: "https://www.youtube.com/embed/ZxFzDJg1l2s" }] }
];

export default function Psychology() {
  const [sub, setSub] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lessons, setLessons] = useState([]);
  const navigate = useNavigate();
  const user = JSON.parse(localStorage.getItem("user")) || null;

  useEffect(() => {
    setSub("Psychology");
    setLessons(PSYCHOLOGY_LESSONS);
    setLoading(false);
  }, []);

  if (loading) return <div>Loading...</div>;

  const handleLessonClick = (lesson) => {
    navigate("/lesson", { state: { lesson } });
  };

  return (
    <div className="page-container">
      <Sidebar />
      <div className="content">
        <h1>{sub}</h1>
        <div className="lessons-grid">
          {lessons.map((lesson) => (
            <div key={lesson.lesson_number} className="lesson-card" onClick={() => handleLessonClick(lesson)}>
              <h3>Lesson {lesson.lesson_number}</h3>
              <p>{lesson.title}</p>
              <span className="video-count">{lesson.videos.length} videos</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
